input.query:
{
  user(id: 7) { id name role avatar createdAt nickname tags settings { theme } friends @count(n: 2) { id name } }
  users(role: ADMIN) { id role }
  pets { __typename name ... on Dog { barks } ... on Cat { lives } }
  search(q: "x") { __typename ... on User { name } ... on Post { title } }
  posts(first: 2) { totalCount pageInfo { hasNextPage endCursor } edges { cursor node { title author { name } } } }
}

options.schema:
scalar DateTime
scalar URL
enum Role { ADMIN EDITOR VIEWER }
interface Animal { name: String! }
type Dog implements Animal { name: String! barks: Boolean! }
type Cat implements Animal { name: String! lives: Int! }
type User { id: ID! name: String! role: Role! avatar: URL createdAt: DateTime! nickname: String tags: [String!]! settings: Settings! friends: [User!]! }
type Settings { theme: String! }
type Post { id: ID! title: String! author: User! }
union Hit = User | Post
type PageInfo { hasNextPage: Boolean! endCursor: String }
type PostEdge { cursor: String! node: Post! }
type PostConnection { edges: [PostEdge!]! pageInfo: PageInfo! totalCount: Int! }
type Query { user(id: ID!): User! users(first: Int = 3, role: Role): [User!]! pets: [Animal!]! search(q: String!): [Hit!]! posts(first: Int, after: String): PostConnection! }
